# Solution

Here's a recursive function that processes messages and converts them to their sendable format:

```python
def convert_messages(messages):
    """
    Recursively converts messages to their sendable format.

    - If the input is a list, processes each element and returns a list.
    - If the input is a tuple, processes each element and returns a tuple.
    - If the input has `_to_outgoing_message()`, calls it.
    - Otherwise, returns the input unchanged.
    """
    if isinstance(messages, list):
        return [convert_messages(msg) for msg in messages]
    elif isinstance(messages, tuple):
        return tuple(convert_messages(msg) for msg in messages)
    elif hasattr(messages, '_to_outgoing_message'):
        return messages._to_outgoing_message()
    else:
        return messages
```

## Example Usage with Sample Classes

```python
class TextMessage:
    def __init__(self, content):
        self.content = content
    def _to_outgoing_message(self):
        return {'type': 'text', 'content': self.content}

class ImageMessage:
    def __init__(self, path):
        self.path = path
    def _to_outgoing_message(self):
        return {'type': 'image', 'path': self.path}

class AudioMessage:
    def __init__(self, url):
        self.url = url
    def _to_outgoing_message(self):
        return {'type': 'audio', 'url': self.url}

class SystemMessage:
    """This class does NOT have _to_outgoing_message(), so it stays unchanged."""
    def __init__(self, content):
        self.content = content
    def __repr__(self):
        return f'SystemMessage("{self.content}")'


# Test
