    TextMessage("Hello, World!"),
    ImageMessage("path/to/image.jpg"),
    SystemMessage("System restarted"),
    (AudioMessage("http://example.com/audio.mp3"), SystemMessage("Audio sent")),
    [TextMessage("Another text message"), ImageMessage("path/to/another/image.jpg")]
]

result = convert_messages(messages)
print(result)
```

