# Almost Similar Strings - Wagner-Fischer Algorithm

## Solution

```python
def almost_similar(s1, s2):
    """
    Determines if two strings are 'almost similar' (Levenshtein distance <= 1).
    Uses the Wagner-Fischer dynamic programming algorithm.

    Returns:
        tuple: (bool, str or None)
            - bool: True if distance <= 1, False otherwise
            - str: description of the edit needed, or None if distance > 1
    """
    m, n = len(s1), len(s2)

    # Wagner-Fischer algorithm: build the DP table
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases: transforming to/from empty string
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Fill the table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # no edit needed
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],      # deletion from s1
                    dp[i][j - 1],      # insertion into s1
                    dp[i - 1][j - 1]   # substitution
                )

    distance = dp[m][n]

    # Determine result based on distance
    if distance == 0:
        return (True, "no edit needed")
    elif distance > 1:
        return (False, None)
    else:
        # Distance is exactly 1 — identify the specific edit
        if m == n:
