def convert_to_list(value, return_empty_list_if_none, convert_tuple_to_list, max_nested_depth):
    """
    Processes an input value according to specific rules and returns a list.

    Args:
        value: The input value to process.
        return_empty_list_if_none: If True and value is None, return empty list.
        convert_tuple_to_list: If True and value is a tuple, convert to list.
        max_nested_depth: Maximum allowed nested depth for lists.

    Returns:
        A list processed according to the rules.
    """

    def get_depth(lst):
        """Calculate the maximum nesting depth of a list."""
        if not isinstance(lst, list):
            return 0
        if len(lst) == 0:
            return 1
        return 1 + max(get_depth(item) for item in lst)

    def flatten_to_depth(lst, depth):
        """Flatten a list to the specified maximum depth."""
        if depth <= 0:
            return lst
        result = []
        for item in lst:
            if isinstance(item, list) and depth > 1:
                result.extend(flatten_to_depth(item, depth - 1))
            else:
                result.append(item)
        return result

    # Handle None
    if value is None:
        if return_empty_list_if_none:
            return []
        else:
            return [None]

    # Handle tuple
    if isinstance(value, tuple):
        if convert_tuple_to_list:
            return list(value)
        else:
            return value

    # Handle list
    if isinstance(value, list):
        current_depth = get_depth(value)
        if current_depth <= max_nested_depth:
            return value
        else:
            return flatten_to_depth(value, max_nested_depth)

    # Handle any other type
    return [value]
