            code_point = byte
            i += 1
        elif byte < 0xE0:
            # 2-byte sequence: 110xxxxx 10xxxxxx
            byte2 = _get_byte_value(byte_sequence, i + 1)
            code_point = ((byte & 0x1F) << 6) | (byte2 & 0x3F)
            i += 2
        elif byte < 0xF0:
            # 3-byte sequence: 1110xxxx 10xxxxxx 10xxxxxx
            byte2 = _get_byte_value(byte_sequence, i + 1)
            byte3 = _get_byte_value(byte_sequence, i + 2)
            code_point = ((byte & 0x0F) << 12) | ((byte2 & 0x3F) << 6) | (byte3 & 0x3F)
            i += 3
        else:
            # 4-byte sequence: 11110xxx 10xxxxxx 10xxxxxx 10xxxxxx
            byte2 = _get_byte_value(byte_sequence, i + 1)
            byte3 = _get_byte_value(byte_sequence, i + 2)
            byte4 = _get_byte_value(byte_sequence, i + 3)
            code_point = ((byte & 0x07) << 18) | ((byte2 & 0x3F) << 12) | \
                         ((byte3 & 0x3F) << 6) | (byte4 & 0x3F)
            i += 4

        result.append(_unichr(code_point))

    return u''.join(result)


def _int_to_string(value):
    """Manually convert an integer to its string representation without using str()."""
    if value == 0:
        return u'0'

    negative = value < 0
    if negative:
        value = -value

    digit_chars = u'0123456789'
    digits = []

    while value > 0:
        digits.append(digit_chars[value % 10])
        value //= 10

    if negative:
        digits.append(u'-')

    digits.reverse()
    return u''.join(digits)


def convert_to_string(value):
    """
    Convert various input types to their string representation.

    - str/unicode: returned unchanged
    - bytes: manually decoded as UTF-8
    - int: manually converted to string

    Compatible with both Python 2 and Python 3.
    Does not use str() or .decode().
