def generate_tikz(nmax, upper_stack, lower_stack):
    lines = []
    lines.append(r"\documentclass{standalone}")
    lines.append(r"\usepackage{tikz}")
    lines.append(r"\begin{document}")
    lines.append(r"\begin{tikzpicture}[every node/.style={draw, minimum width=2em, minimum height=2em, align=center}]")

    # Upper stack: element i is at position (i, nmax + len(upper_stack) - i)
    for i, elem in enumerate(upper_stack):
        x = i
        y = nmax + len(upper_stack) - i
        lines.append(f"\t\\node at ({x},{y}) {{{elem}}};")

    # Lower stack: element i is at position (i, -(nmax - len(lower_stack) + 1) - i)
    for i, elem in enumerate(lower_stack):
        x = i
        y = -(nmax - len(lower_stack) + 1) - i
        lines.append(f"\t\\node at ({x},{y}) {{{elem}}};")

    lines.append(r"\end{tikzpicture}")
    lines.append(r"\end{document}")

    return "\n".join(lines)


