import re
from bs4 import BeautifulSoup


def extract_suitable_image_url(html_content):
    banned = ["doubleclick", "feedburner", "tweetmeme", "hulkshare", "tracker", "phobos", "apple"]

    def is_suitable(url):
        return not any(b in url for b in banned)

    soup = BeautifulSoup(html_content, 'html.parser')

    # Extract CSS rules from <style> tags
    css_rules = {}
    for style_tag in soup.find_all('style'):
        css_text = style_tag.string or ''
        # Match selectors with background-image url
        rule_pattern = re.compile(
            r'([^{]+)\{([^}]*background-image\s*:\s*url\(\s*[\'"]?([^\'")\s]+)[\'"]?\s*\)[^}]*)\}'
        )
        for match in rule_pattern.finditer(css_text):
            selector = match.group(1).strip()
            url = match.group(3)
            css_rules[selector] = url

    def get_background_url_from_style(style_str):
        """Extract background-image URL from an inline style string."""
        if not style_str:
            return None
        bg_match = re.search(
            r'background-image\s*:\s*url\(\s*[\'"]?([^\'")\s]+)[\'"]?\s*\)', style_str
        )
        if bg_match:
            return bg_match.group(1)
        return None

    def selector_matches_element(selector, element):
        """Check if a CSS selector matches a given element."""
        selector = selector.strip()
        if selector.startswith('.'):
            class_name = selector[1:]
            element_classes = element.get('class', [])
            return class_name in element_classes
        elif selector.startswith('#'):
            id_name = selector[1:]
            return element.get('id', '') == id_name
        else:
            return element.name == selector

    # Iterate through all <img> elements in document order
    for img in soup.find_all('img'):
        # 1. Check the img's src attribute
        src = img.get('src', '')
        if src and is_suitable(src):
            return src

        # 2. Check inline background-image on the <img> itself
        bg_url = get_background_url_from_style(img.get('style', ''))
        if bg_url and is_suitable(bg_url):
            return bg_url

        # 3. Check CSS rules that apply to the <img> element itself
        for selector, url in css_rules.items():
            if selector_matches_element(selector, img):
                if is_suitable(url):
                    return url

        # 4. Check the direct parent element
        parent = img.parent
        if parent:
            # Check parent's inline style
            bg_url = get_background_url_from_style(parent.get('style', ''))
            if bg_url and is_suitable(bg_url):
                return bg_url

            # Check CSS rules that apply to the parent
            for selector, url in css_rules.items():
                if selector_matches_element(selector, parent):
                    if is_suitable(url):
                        return url

    return ""
```

**How it works:**

1. **Parse the HTML** using BeautifulSoup.
2. **Extract CSS rules** from `<style>` tags, specifically looking for `background-image: url(...)` declarations.
3. **Iterate through `<img>` elements** in document order. For each one:
